export const verifyPersonalTaxComputationPack = (runner: BusinessSessionRunner, envelope: CommandEnvelope<ComputationPackDecisionPayload>) => decidePack(runner, envelope, "HUMAN_VERIFIED");
export const rejectPersonalTaxComputationPack = (runner: BusinessSessionRunner, envelope: CommandEnvelope<ComputationPackDecisionPayload>) => decidePack(runner, envelope, "REJECTED");
export async function showPersonalTaxComputationPack(runner: BusinessSessionRunner, packId: string): Promise<JsonObject> { return runner.withBusinessSession("read", async (session) => { const row = await packRow(session, text(packId, "packId")); return packView(row, await lifecycle(session, packId)); }); }

