async function validateEligibilityFacts(session: BusinessSession, tenantId: string, payload: ComputationInputsRecordPayload, pack: JsonObject): Promise<void> {
  const program = JSON.parse(String(pack.program_json)) as Program;
  for (const node of program.nodes.filter((candidate) => candidate.op === "conditional")) {
    const field = String(node.fact); const supplied = payload.inputs?.[field];
    const fact = await session.querySingle("SELECT value_type, value_json, verification_state FROM tax_case_itr_eligibility_facts WHERE tenant_id = ? AND tax_case_id = ? AND filing_snapshot_id = ? AND worksheet_id = ? AND field_name = ? ORDER BY created_at DESC, id DESC LIMIT 1", [tenantId, payload.taxCaseId, payload.filingSnapshotId, payload.worksheetId, field]);
    if (!fact || String(fact.verification_state) !== "HUMAN_VERIFIED") throw new DomainError("TAX_COMPUTATION_ELIGIBILITY_FACT_UNVERIFIED", `conditional eligibility fact ${field} is not HUMAN_VERIFIED`);
    if (!supplied || supplied.value !== JSON.parse(String(fact.value_json))) throw new DomainError("TAX_COMPUTATION_ELIGIBILITY_FACT_MISMATCH", `conditional eligibility fact ${field} does not match the exact HUMAN_VERIFIED fact`);
  }
}

