async function evaluationStatus(session: BusinessSession, row: JsonObject): Promise<string> { const pack = await session.querySingle("SELECT id, canonical_hash FROM personal_tax_authority_packs WHERE id = ?", [row.pack_id]); return pack && String(pack.canonical_hash) === String(row.pack_hash) && String(row.snapshot_candidate_hash) === String((await filingSnapshotStateInSession(session, String(row.tenant_id), String(row.tax_case_id), String(row.filing_snapshot_id))).candidateHash) ? "CURRENT" : "STALE"; }

