export async function previewPersonalTaxComputation(runner: BusinessSessionRunner, tenantId: string, payload: ComputationInputsRecordPayload): Promise<JsonObject> { return runner.withBusinessSession("read", async (session) => { const pack = await packRow(session, text(payload.computationPackId, "computationPackId")); const binding = await currentBinding(session, text(tenantId, "tenantId"), payload, pack); const program = JSON.parse(String(pack.program_json)) as Program; const evaluated = evaluateProgram(program, binding.inputs); return computationView(pack, binding, evaluated, undefined); }); }
