export async function showPersonalTaxComputation(runner: BusinessSessionRunner, tenantId: string, taxCaseId: string, computationId: string): Promise<JsonObject> {
  return runner.withBusinessSession("read", async (session) => {
    const row = await session.querySingle("SELECT * FROM personal_tax_computations WHERE id = ? AND tenant_id = ? AND tax_case_id = ?", [computationId, tenantId, taxCaseId]);
    if (!row) throw new DomainError("TAX_COMPUTATION_NOT_FOUND", "computation does not belong to TaxCase and tenant");
    const pack = await packRow(session, String(row.computation_pack_id));
    const packLifecycle = await lifecycle(session, String(pack.id));
    const snapshot = await filingSnapshotStateInSession(session, tenantId, taxCaseId, String(row.filing_snapshot_id));
    const current = String(row.snapshot_candidate_hash) === snapshot.candidateHash && snapshot.status === "CURRENT" && packLifecycle === "HUMAN_VERIFIED";
    const status = current ? "CURRENT" : "STALE";
    return { computationId, tenantId, taxCaseId, workpaper: "WORKPAPER_NOT_RETURN", status, statusReasons: status === "CURRENT" ? [] : ["UPSTREAM_REVISION"], computationHash: String(row.computation_hash), computationPackId: String(row.computation_pack_id), computationPackHash: String(row.computation_pack_hash), inputSetId: String(row.input_set_id), inputHash: String(row.input_hash), snapshotCandidateHash: String(row.snapshot_candidate_hash), worksheetOutputHash: String(row.worksheet_output_hash), evaluationHash: String(row.evaluation_hash), selectionHash: String(row.selection_hash), trace: JSON.parse(String(row.step_trace_json)), namedSchedules: JSON.parse(String(row.named_schedules_json)), grossTaxMinor: String(row.gross_tax_minor), creditsMinor: String(row.credits_minor), ...(row.net_payable_minor == null ? { refundMinor: String(row.refund_minor) } : { netPayableMinor: String(row.net_payable_minor) }), lifecycle: String(row.lifecycle), packLifecycle };
  });
}
export async function statusPersonalTaxComputation(runner: BusinessSessionRunner, tenantId: string, taxCaseId: string, computationId: string): Promise<JsonObject> { const view = await showPersonalTaxComputation(runner, tenantId, taxCaseId, computationId); return { computationId, tenantId, taxCaseId, status: view.status, statusReasons: view.statusReasons, lifecycle: view.lifecycle }; }
export async function approvePersonalTaxComputation(runner: BusinessSessionRunner, envelope: CommandEnvelope<ComputationApprovePayload>): Promise<CommandResult<Record<string, unknown>>> { validateCommandEnvelope(envelope); if (envelope.actor.kind !== "HUMAN") throw new DomainError("TAX_COMPUTATION_APPROVAL_HUMAN_REQUIRED", "computation approval requires a HUMAN actor"); const payload = { taxCaseId: text(envelope.payload?.taxCaseId, "taxCaseId"), computationId: text(envelope.payload?.computationId, "computationId"), expectedComputationHash: sha(envelope.payload?.expectedComputationHash, "expectedComputationHash"), reason: text(envelope.payload?.reason, "reason") }; const requestHash = computeCommandHash(APPROVE, envelope, payload); return runner.withBusinessSession("write", async (session) => { const prior = await replay(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const row = await session.querySingle("SELECT * FROM personal_tax_computations WHERE id = ? AND tenant_id = ? AND tax_case_id = ?", [payload.computationId, envelope.tenantId, payload.taxCaseId]); if (!row) throw new DomainError("TAX_COMPUTATION_NOT_FOUND", "computation does not belong to TaxCase and tenant"); if (String(row.computation_hash) !== payload.expectedComputationHash) throw new DomainError("TAX_COMPUTATION_APPROVAL_CAS_MISMATCH", "expected computation hash does not match"); const snapshot = await filingSnapshotStateInSession(session, envelope.tenantId, payload.taxCaseId, String(row.filing_snapshot_id)); if (snapshot.status !== "CURRENT" || String(row.snapshot_candidate_hash) !== snapshot.candidateHash) throw new DomainError("TAX_COMPUTATION_NOT_CURRENT", "only a CURRENT computation can be approved"); if (await lifecycle(session, String(row.computation_pack_id)) !== "HUMAN_VERIFIED") throw new DomainError("TAX_COMPUTATION_NOT_CURRENT", "the bound computation pack is no longer HUMAN_VERIFIED"); const now = new Date().toISOString(); await session.execute("INSERT INTO personal_tax_computation_events (id, tenant_id, tax_case_id, computation_id, event_type, actor_kind, actor_id, reason, expected_computation_hash, request_id, request_hash, created_at) VALUES (?, ?, ?, ?, 'APPROVED', 'HUMAN', ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, payload.taxCaseId, payload.computationId, envelope.actor.id, payload.reason, payload.expectedComputationHash, envelope.requestId, requestHash, now]); return finish(session, APPROVE, envelope, requestHash, { computationId: payload.computationId, computationHash: payload.expectedComputationHash, status: "APPROVED", workpaper: "WORKPAPER_NOT_RETURN" }, payload.computationId, "PersonalTaxComputation"); }); }
